/*EF_ACCT_NAME*/try{localStorage.setItem('EF_LAST_SECTION','diet');}catch(e){}var _efAccName=null;if(C&&typeof C.summary==='function'){var _efOrigSummary=C.summary.bind(C);C.summary=function(){var s=_efOrigSummary()||{};if(_efAccName)s.name=_efAccName;return s;};}try{fetch('/api/auth/me',{credentials:'include'}).then(function(r){return r.json();}).then(function(d){var u=d&&(d.user||d);if(u&&u.name){_efAccName=u.name;}if(d&&d.subscription){window.EF_SUB=d.subscription;}if((u&&u.name||d&&d.subscription)&&root&&typeof render==='function')render();}).catch(function(){});}catch(e){}
var root=document.getElementById('dashRoot');
var state={tab:'today',selDate:todayKey(),anScope:'week',mealOpen:null,suppPanel:false,suppOpen:null,pickSlot:null,pickQ:'',pickCat:'all',pickFoodId:null};
function todayKey(){return new Date().toISOString().slice(0,10);}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function el(id){return document.getElementById(id);}
function ar(n){try{return Number(n).toLocaleString('ar-EG');}catch(e){return n;}}

/* حلقة SVG */
function ring(pct,size,color,label,sub){
  size=size||120;var r=(size-14)/2;var cx=size/2;var circ=2*Math.PI*r;var off=circ*(1-clamp(pct,0,100)/100);
  return '<div class="hring" style="width:'+size+'px;height:'+size+'px">'+
    '<svg viewBox="0 0 '+size+' '+size+'">'+
    '<circle cx="'+cx+'" cy="'+cx+'" r="'+r+'" fill="none" stroke="rgba(255,255,255,.25)" stroke-width="10"/>'+
    '<circle cx="'+cx+'" cy="'+cx+'" r="'+r+'" fill="none" stroke="'+(color||'#fff')+'" stroke-width="10" stroke-linecap="round" stroke-dasharray="'+circ+'" stroke-dashoffset="'+off+'" transform="rotate(-90 '+cx+' '+cx+')"/>'+
    '</svg><div class="hlab"><b>'+label+'</b><span>'+sub+'</span></div></div>';
}
function dial(pct,color,val,sub){
  var size=94,r=40,cx=47,circ=2*Math.PI*r;var off=circ*(1-clamp(pct,0,100)/100);
  return '<div class="dial"><svg viewBox="0 0 94 94">'+
    '<circle cx="47" cy="47" r="40" fill="none" stroke="#eef2ec" stroke-width="9"/>'+
    '<circle cx="47" cy="47" r="40" fill="none" stroke="'+color+'" stroke-width="9" stroke-linecap="round" stroke-dasharray="'+circ+'" stroke-dashoffset="'+off+'"/>'+
    '</svg><div class="c">'+val+(sub?'<small>'+sub+'</small>':'')+'</div></div>';
}
function clamp(n,a,b){return Math.max(a,Math.min(b,n));}

/* ============ حالة فارغة ============ */
