  // نستخدم نفس كلاسات wlog الجميلة
  var html='<div class="wlog">';
  html+='<div class="wlog-title">\u2696\uFE0F \u0633\u062c\u0651\u0644 \u062a\u0642\u062f\u0651\u0645\u0643</div>';
  html+='<div class="wgrid">';
  html+='<div class="wfield"><label>\u0627\u0644\u0648\u0632\u0646 (\u0643\u062c\u0645)</label><input id="wInput" type="number" step="0.1" placeholder="'+(lastW||'70')+'"></div>';
  html+='<div class="wfield"><label>\uD83D\uDCCF \u0627\u0644\u0628\u0637\u0646/\u0627\u0644\u062e\u0635\u0631 (\u0633\u0645)</label><input id="mWaist" type="number" step="0.1" placeholder="'+(lw||'\u2014')+'"></div>';
  html+='<div class="wfield"><label>\uD83E\uDDB5 \u0627\u0644\u0641\u062e\u0630 (\u0633\u0645)</label><input id="mThigh" type="number" step="0.1" placeholder="'+(lt||'\u2014')+'"></div>';
  html+='<div class="wfield"><label>\uD83D\uDCAA \u0627\u0644\u0632\u0631\u0627\u0639 (\u0633\u0645)</label><input id="mArm" type="number" step="0.1" placeholder="'+(la||'\u2014')+'"></div>';
  html+='</div>';
  html+='<div class="wlog-hint">\u0627\u0644\u0645\u0642\u0627\u0633\u0627\u062a \u062a\u062e\u0644\u064a خبير التغذية \u064a\u0639\u062f\u0651\u0644 \u0627\u0644\u062e\u0637\u0629 \u0635\u062d \u062d\u062a\u0649 \u0644\u0648 \u0627\u0644\u0648\u0632\u0646 \u062b\u0627\u0628\u062a</div>';
  html+='<button onclick="DASH.logWeight()">\u062d\u0641\u0638</button>';
