function renderMobNav(){
  var old=el('mobNav');if(old)old.remove();
  var nav=document.createElement('nav');nav.id='mobNav';nav.className='mobnav';
  var items=[['profile','البروفايل',''],['analysis','التحليل',''],['today','وجبات اليوم',' mn-plus'],['coach','خبير التغذية',''],['info','نصائح','']];
  for(var i=0;i<items.length;i++){(function(it){var b=document.createElement('button');b.className='mn-item'+it[2]+(state.tab===it[0]?' on':'');b.innerHTML=mobSvg(it[0])+'<span>'+it[1]+'</span>';b.onclick=function(){DASH.go(it[0]);};nav.appendChild(b);})(items[i]);}
  document.body.appendChild(nav);
}
